func run() -> Vector2:
	var position: Vector2 = Vector2(100.0, 150.0)
	var displacement: Vector2 = Vector2(40.0, -30.0)
	return position + displacement

func run() -> Vector2:
	var direction: Vector2 = Vector2(0.0, 1.0)
	var speed: float = 180.0
	var delta: float = 0.5
	return direction * speed * delta

func run() -> Vector2:
	var velocity: Vector2 = Vector2(3.0, 4.0)
	return velocity.normalized()

func run() -> Vector2:
	var from_pos: Vector2 = Vector2(200.0, 100.0)
	var to_pos: Vector2 = Vector2(200.0, 350.0)
	return from_pos.direction_to(to_pos)

func run() -> Vector2:
	var current_pos: Vector2 = Vector2(50.0, 100.0)
	var target_pos: Vector2 = Vector2(90.0, 100.0)
	var step: float = 60.0
	return current_pos.move_toward(target_pos, step)

func run() -> float:
	var diagonal_input: Vector2 = Vector2(1.0, 1.0)
	var normalized_dir: Vector2 = diagonal_input.normalized()
	return normalized_dir.length()
